create function public.create_quote_atomic(p_rfq_id uuid,p_vendor_name text,p_raw_text text,p_currency char(3),p_freight numeric,p_tax numeric,p_discount numeric,p_delivery integer,p_payment_terms text,p_items jsonb) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_quote uuid:=gen_random_uuid();v_item jsonb;begin if auth.uid() is null or not exists(select 1 from public.rfq_sessions where id=p_rfq_id and user_id=auth.uid()) then raise exception 'not authorized';end if;insert into public.vendor_quotes(id,rfq_id,vendor_name,raw_text,currency,freight_cost,tax_amount,discount_amount,delivery_days,payment_terms) values(v_quote,p_rfq_id,p_vendor_name,nullif(p_raw_text,''),p_currency,p_freight,p_tax,p_discount,p_delivery,nullif(p_payment_terms,''));for v_item in select value from jsonb_array_elements(p_items) loop insert into public.quote_items(rfq_id,quote_id,rfq_item_id,description,quantity,unit_price,unit,line_total) values(p_rfq_id,v_quote,(v_item->>'rfqItemId')::uuid,nullif(v_item->>'description',''),(v_item->>'quantity')::numeric,nullif(v_item->>'unitPrice','')::numeric,nullif(v_item->>'unit',''),nullif(v_item->>'lineTotal','')::numeric);end loop;return v_quote;end $$;
revoke all on function public.create_quote_atomic(uuid,text,text,char(3),numeric,numeric,numeric,integer,text,jsonb) from public,anon;
grant execute on function public.create_quote_atomic(uuid,text,text,char(3),numeric,numeric,numeric,integer,text,jsonb) to authenticated;
